import { router, userProcedure } from '../trpc';
import { observable } from '@trpc/server/observable';
import { TRPCError } from '@trpc/server';
import { z } from 'zod';
import { buildLogEmitter } from '../services/ciRunner';

export const buildLogRouter = router({
  streamPipelineLogs: userProcedure
    .input(z.object({ pipelineRunId: z.string() }))
    .subscription(async ({ input, ctx }) => {
      // Verify that the pipeline run belongs to a repository the user can access
      const run = await ctx.prisma.pipelineRun.findUnique({
        where: { id: input.pipelineRunId },
        select: { repository: { select: { organizationId: true, isPrivate: true } } }
      });

      if (!run) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'Pipeline run not found' });
      }

      if (run.repository.isPrivate) {
        const membership = await ctx.prisma.organizationMember.findFirst({
          where: {
            organizationId: run.repository.organizationId,
            userId: ctx.user.id
          }
        });

        if (!membership) {
          throw new TRPCError({
            code: 'FORBIDDEN',
            message: 'Access denied: not a member of the repository organization'
          });
        }
      }

      return observable<string>((emit) => {
        const handler = (event: { runId: string; chunk: string }) => {
          if (event.runId === input.pipelineRunId) {
            emit.next(event.chunk);
          }
        };

        buildLogEmitter.on('log_chunk', handler);
        return () => {
          buildLogEmitter.off('log_chunk', handler);
        };
      });
    }),
});
